using System;

class Player
{
    static int ParseTime(string hhmm)
    {
        string[] p = hhmm.Split(':');
        return int.Parse(p[0]) * 60 + int.Parse(p[1]);
    }

    static string FormatTime(int totalMinutes)
    {
        int day = 24 * 60;
        totalMinutes %= day;
        if (totalMinutes < 0) totalMinutes += day;
        int h = totalMinutes / 60;
        int m = totalMinutes % 60;
        return $"{h:D2}:{m:D2}";
    }

    static void Main(string[] args)
    {
        string s = Console.ReadLine();
        int n = int.Parse(Console.ReadLine());

        string[] parts = s.Split('|');
        string flight = parts[0];
        string origin = parts[1];
        string dest = parts[2];
        int departureMinutes = ParseTime(parts[3]);

        for (int i = 0; i < n; i++)
        {
            string cmd = Console.ReadLine();

            if (cmd == "SWAP_STATIONS")
            {
                string tmp = origin;
                origin = dest;
                dest = tmp;
                continue;
            }

            string[] cmdParts = cmd.Split('|');
            string op = cmdParts[0];

            if (op == "SET_ORIGIN")
            {
                origin = cmdParts[1];
            }
            else if (op == "SET_DEST")
            {
                dest = cmdParts[1];
            }
            else if (op == "SET_DEPARTURE")
            {
                departureMinutes = ParseTime(cmdParts[1]);
            }
            else if (op == "DELAY")
            {
                departureMinutes += int.Parse(cmdParts[1]);
            }
        }

        Console.WriteLine($"{flight}|{origin}|{dest}|{FormatTime(departureMinutes)}");
    }
}
